let tex = '';
if (!fs.existsSync(path.join(import.meta.dirname, 'index.html'))) {
  try { tex = fs.readFileSync(path.join(root, 'prelibro-catalogo-cobria.tex'), 'utf8'); }
  catch { tex = ''; }
}

function balanced(text, start) {
  let depth = 0;
  for (let i = start; i < text.length; i++) {
    if (text[i] === '{') depth++;
    if (text[i] === '}' && --depth === 0) return [text.slice(start + 1, i), i + 1];
  }
  throw new Error('Llave sin cierre');
}

const patterns = [];
let cursor = 0;
while ((cursor = tex.indexOf('\\Ficha{', cursor)) >= 0) {
  let at = cursor + '\\Ficha'.length;
  const fields = [];
  for (let i = 0; i < 9; i++) {
    while (/\s/.test(tex[at])) at++;
    const [value, next] = balanced(tex, at);
    fields.push(value); at = next;
  }
  patterns.push(fields); cursor = at;
}
if (patterns.length === 0) {
  const previous = fs.readFileSync(path.join(import.meta.dirname, 'index.html'), 'utf8');
  const strip = value => value.replace(/<[^>]+>/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/\s+/g,' ').trim();
  for (const hit of previous.matchAll(/<article class="pattern[^>]*>([\s\S]*?)<\/article>/g)) {
    const block = hit[1];
    const title = strip((block.match(/<h1>([\s\S]*?)<\/h1>/)||[])[1]||'');
    const badges = [...block.matchAll(/<span class="badge">([\s\S]*?)<\/span>/g)].map(x=>strip(x[1]).replace(/^Evidencia:\s*/,''));
    const bodies = [...block.matchAll(/<section class="block[^>]*>[\s\S]*?<p>([\s\S]*?)<\/p><\/section>/g)].map(x=>strip(x[1]));
    if (title && badges.length === 2 && bodies.length === 6) patterns.push([title,...badges,...bodies]);
  }
}

