function clean(value) {
  return value
    .replace(/``([^']+)''/g, '“$1”')
    .replace(/\\Delta/g, 'Δ').replace(/\\ll/g, '≪').replace(/\\leq/g, '≤')
    .replace(/\\,/g, ' ').replace(/~|\\par/g, ' ')
    .replace(/\\text(?:bf|sf)\{([^{}]+)\}/g, '$1')
    .replace(/\$([^$]+)\$/g, '<em>$1</em>')
    .replace(/--/g, '—').replace(/\\/g, '')
    .replace(/\s+/g, ' ').trim();
}

