fs.writeFileSync(path.join(import.meta.dirname, 'cuaderno.html'), workbookHtml);
fs.writeFileSync(path.join(import.meta.dirname, 'anexo-tecnico.html'), technicalAnnexHtml);
const sitePublic = path.resolve(root, '..', 'COBRIA-atlas', 'public');
if (fs.existsSync(path.dirname(sitePublic))) {
  fs.mkdirSync(sitePublic, { recursive: true });
  const catalogo = patterns.map((p,index) => ({
    id: index + 1,
    slug: clean(p[0]).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,''),
    nombre: clean(p[0]), familia: familyByPattern[index], tipo: clean(p[1]), evidencia: clean(p[2]),
    proposito: clean(p[3]), problema: clean(p[4]), analogia: clean(p[5]), solucion: clean(p[6]),
    aplicacion: clean(p[7]), metricas: clean(p[8]), contrato: contracts[index], ejercicio: exercises[index],
    relaciones: related(index)
  }));
  fs.writeFileSync(path.join(sitePublic, 'catalogo.json'), JSON.stringify(catalogo, null, 2));
}
console.log(`Libro construido con ${patterns.length} fichas.`);
